package com.restaurantmanagement.controller; import com.restaurantmanagement.dto.*; import com.restaurantmanagement.entity.OrderStatus; import com.restaurantmanagement.service.OrderService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service;public OrderController(OrderService s){service=s;} @GetMapping public List<OrderResponse> list(){return service.list();} @PostMapping public ResponseEntity<OrderResponse> create(@Valid @RequestBody OrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PatchMapping("/{id}/status") public OrderResponse status(@PathVariable Long id,@RequestParam OrderStatus status){return service.transition(id,status);} }
